import org.audiveris.omr.sheet.Book;
import java.nio.file.*;import java.util.*;
public class RealTimeColumnFailureImageProbe extends RealLedgerMembershipImageProbe {
 private final Object actual;
 public RealTimeColumnFailureImageProbe(Book book,SortedSet<Integer> ids){super(book,ids);actual=book;}
 static String body(Object n)throws Exception {Object staff=call(n,"getStaff");return "{\"id\":"+call(n,"getId")+",\"kind\":\""+n.getClass().getSimpleName()+"\",\"bounds\":"+rect(call(n,"getBounds"))+",\"grade\":"+call(n,"getGrade")+",\"manual\":"+call(n,"isManual")+",\"removed\":"+call(n,"isRemoved")+",\"staff\":"+(staff==null?"null":call(staff,"getId"))+"}";}
 public void process(){try {
 Object stub=((List<?>)call(actual,"getStubs")).get(0);call(stub,"reachStep",c("step.OmrStep").getField("CHORDS").get(null),false);Object sheet=call(stub,"getSheet");Map<Object,List<?>> optionals=new LinkedHashMap<>();call(make("sheet.symbol.SymbolsFilter",sheet),"process",optionals);List<String> systems=new ArrayList<>();
 for(Object sys:(List<?>)call(sheet,"getSystems")){
 Object sig=call(sys,"getSig"),factory=make("sheet.symbol.InterFactory",sys);call(make("sheet.symbol.SymbolsBuilder",sys,factory),"buildSymbols",optionals);call(make("sheet.note.ChordsBuilder",sys),"buildRestChords");var f=factory.getClass().getDeclaredField("dotFactory");f.setAccessible(true);call(f.get(factory),"lateDotChecks");call(factory,"handleComplexDynamics");
 List<Object> all=new ArrayList<>((Set<?>)call(sig,"vertexSet"));List<String> before=new ArrayList<>(),times=new ArrayList<>();
 for(Object n:all){before.add(body(n));if(Set.of("TimeWholeInter","TimeCustomInter","TimeNumberInter").contains(n.getClass().getSimpleName())){Object staff=call(n,"getStaff"),center=call(n,"getCenter"),stack=call(sys,"getStackAt",center);times.add("{\"body\":"+body(n)+",\"header_stop\":"+call(staff,"getHeaderStop")+",\"center_x\":"+((java.awt.Point)center).x+",\"stack_id\":"+(stack==null?"null":call(stack,"getIdValue"))+"}");}}
 List<String> columns=new ArrayList<>();Map<Integer,LinkedHashSet<Object>> groups=new TreeMap<>();Map<Integer,Object> stacks=new TreeMap<>();
 for(Object n:all)if(n.getClass().getSimpleName().equals("TimeWholeInter")){Object staff=call(n,"getStaff"),point=call(n,"getCenter");if(((java.awt.Point)point).x<((Number)call(staff,"getHeaderStop")).intValue())continue;Object stack=call(sys,"getStackAt",point);if(stack!=null){int id=((Number)call(stack,"getIdValue")).intValue();groups.computeIfAbsent(id,k->new LinkedHashSet<>()).add(n);stacks.put(id,stack);}}
 for(var entry:groups.entrySet()){Object column=make("sheet.time.BasicTimeColumn",stacks.get(entry.getKey()),entry.getValue());List<String> trace=new ArrayList<>();boolean failed=false;
 for(Object staff:(List<?>)call(sys,"getStaves")){Object builder=call(column,"allocateBuilder",staff);call(builder,"findCandidates");List<String> candidates=new ArrayList<>(),contacts=new ArrayList<>();for(Object time:entry.getValue())if(call(time,"getStaff")==staff){candidates.add(body(time));for(Object neighbor:new ArrayList<>((Set<?>)call(sig,"vertexSet")))if(!entry.getValue().contains(neighbor)&&((java.awt.Rectangle)call(neighbor,"getBounds")).intersects((java.awt.Rectangle)call(time,"getBounds"))&&!neighbor.getClass().getSimpleName().endsWith("ChordInter")&&!neighbor.getClass().getSimpleName().equals("TimePairInter")){contacts.add("{\"time\":"+body(time)+",\"neighbor\":"+body(neighbor)+",\"overlap\":"+call(neighbor,"overlaps",time)+"}");}}
 boolean ok=(Boolean)call(builder,"filterCandidates");List<String> state=new ArrayList<>();for(Object t:entry.getValue())state.add(body(t));trace.add("{\"staff\":"+call(staff,"getId")+",\"candidates\":["+String.join(",",candidates)+"],\"neighbors\":["+String.join(",",contacts)+"],\"filter_result\":"+ok+",\"after_filter\":["+String.join(",",state)+"]}");if(!ok){call(column,"cleanup");failed=true;break;}}
 if(!failed)throw new IllegalStateException("positive column not this observer scope");columns.add("{\"stack_id\":"+entry.getKey()+",\"trace\":["+String.join(",",trace)+"]}");}
 List<String> after=new ArrayList<>();for(Object n:all)after.add(body(n));systems.add("{\"system\":"+call(sys,"getId")+",\"columns\":["+String.join(",",columns)+"],\"times\":["+String.join(",",times)+"],\"before\":["+String.join(",",before)+"],\"after\":["+String.join(",",after)+"]}");}
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"scope\":\"unchanged image SymbolsBuilder then RestChords then lateDotChecks then handleComplexDynamics; original allocateBuilder/findCandidates/filterCandidates/cleanup calls in pinned retrieveTime order; actual first failed Staff intermediate states, removed original object references retained, no native inputs\",\"systems\":["+String.join(",",systems)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
